import React, { useEffect, useMemo, useState } from "react";
import { Box, Text, useInput } from "ink";
import { LOGO_ROWS, LOGO_WIDTH } from "../generated/logo.ts";
import { theme } from "../theme.ts";

/**
 * Terminal port of the embedme.html logo intro: outside-in stroke draw,
 * light sweep across the mark, then the wordmark cascades in with an
 * orange shimmer over GLINT. Any key skips.
 */

const DRAW_MS = 1050;
const SWEEP_START = DRAW_MS + 80;
const SWEEP_MS = 520;
const WORD_START = SWEEP_START + SWEEP_MS + 120;
const LETTER_STEP = 42;
const WORD = "GLINT RESEARCH";
const SHIMMER_START = WORD_START + WORD.length * LETTER_STEP + 250;
const SHIMMER_MS = 700;
const TOTAL = SHIMMER_START + SHIMMER_MS + 350;
const FPS_MS = 33;

interface Cell {
  row: number;
  col: number;
  ch: string;
  revealAt: number;
}

function buildCells(): Cell[] {
  const cy = LOGO_ROWS.length / 2;
  const cx = LOGO_WIDTH / 2;
  const cells: Cell[] = [];
  let maxDist = 0;
  for (let r = 0; r < LOGO_ROWS.length; r++) {
    for (let c = 0; c < LOGO_ROWS[r].length; c++) {
      const ch = LOGO_ROWS[r][c];
      if (ch === " ") continue;
      // Braille cells are ~2x taller than wide; weight rows for a round wave.
      const dist = Math.hypot((r - cy) * 2, c - cx);
      maxDist = Math.max(maxDist, dist);
      cells.push({ row: r, col: c, ch, revealAt: dist });
    }
  }
  for (const cell of cells) {
    // outside-in: farthest cells draw first.
    cell.revealAt = (1 - cell.revealAt / maxDist) * DRAW_MS;
  }
  return cells;
}

export function Intro({ onDone }: { onDone: () => void }): React.ReactElement {
  const cells = useMemo(buildCells, []);
  const [t, setT] = useState(0);

  useInput(() => onDone());

  useEffect(() => {
    const started = Date.now();
    const timer = setInterval(() => {
      const elapsed = Date.now() - started;
      if (elapsed >= TOTAL) {
        clearInterval(timer);
        onDone();
        return;
      }
      setT(elapsed);
    }, FPS_MS);
    return () => clearInterval(timer);
  }, [onDone]);

  const sweepActive = t >= SWEEP_START && t < SWEEP_START + SWEEP_MS;
  const sweepPos = sweepActive
    ? ((t - SWEEP_START) / SWEEP_MS) * (LOGO_WIDTH + LOGO_ROWS.length * 2 + 24) - 12
    : -1;

  const rows: React.ReactElement[] = [];
  for (let r = 0; r < LOGO_ROWS.length; r++) {
    const rowCells = cells.filter((c) => c.row === r);
    let line: React.ReactNode[] = [];
    let cursor = 0;
    let chunk = "";
    let chunkBright = false;
    const flush = (key: number) => {
      if (!chunk) return;
      line.push(
        <Text key={key} bold={chunkBright} color={chunkBright ? "#FFFFFF" : theme.ink}>
          {chunk}
        </Text>,
      );
      chunk = "";
    };
    let key = 0;
    for (const cell of rowCells) {
      const visible = cell.revealAt <= t;
      const bright = sweepActive && Math.abs(cell.col + cell.row * 2 - sweepPos) < 7;
      if (cell.col > cursor) {
        flush(key++);
        chunk = " ".repeat(cell.col - cursor);
        chunkBright = false;
        flush(key++);
      }
      if (bright !== chunkBright) flush(key++);
      chunkBright = bright;
      chunk += visible ? cell.ch : " ";
      cursor = cell.col + 1;
    }
    flush(key++);
    rows.push(<Text key={r}>{line.length > 0 ? line : " "}</Text>);
  }

  const letters: React.ReactNode[] = [];
  const shimmerT = (t - SHIMMER_START) / SHIMMER_MS;
  for (let i = 0; i < WORD.length; i++) {
    const ch = WORD[i];
    const visible = t >= WORD_START + i * LETTER_STEP;
    const isGlint = i < 5;
    let color = isGlint ? theme.orange : theme.ink;
    let bold = isGlint;
    if (visible && isGlint && shimmerT >= 0 && shimmerT <= 1) {
      const wave = shimmerT * 8 - i;
      if (wave > -1 && wave < 1.6) {
        color = theme.amber;
        bold = true;
      }
    }
    letters.push(
      <Text key={i} bold={bold} color={color}>
        {visible ? ch : " "}
      </Text>,
    );
  }
  const wordSpaced = letters.flatMap((l, i) => (i === 0 ? [l] : [<Text key={`s${i}`}> </Text>, l]));
  const wordWidth = WORD.length * 2 - 1;
  const pad = Math.max(0, Math.floor((LOGO_WIDTH - wordWidth) / 2));

  return (
    <Box flexDirection="column" paddingLeft={2} paddingTop={1} paddingBottom={1}>
      {rows}
      <Box marginTop={1} marginLeft={pad + (t >= WORD_START ? 0 : 0)}>
        <Text>{wordSpaced}</Text>
      </Box>
      <Box marginLeft={pad}>
        <Text color={theme.faint} dimColor>
          {t > WORD_START ? "  we teach tiny neural networks to think" : " "}
        </Text>
      </Box>
    </Box>
  );
}
